var OVK={"شهاداتي":["Мафъул биҳ","Жамъ муаннас солим: насб аломати касра. ي — мутакаллим олмоши (мудоф илайҳ)"],"مهندسين":["Мудоф илайҳ, мажрур","Жамъ музаккар солим: жарр аломати ي, охиридаги ن фатҳа олади"],"أبي":["Мунодо мудоф","Мансуб, лекин ي га уланганлиги учун ҳаракати кўринмайди"],"سنتين":["Мажрур","Мутсанно: жарр аломати ي, охиридаги ن касра олади"],"أعمل":["","Мажзум: لَمْ дан кейин жазм аломати сукун"],"يجدون":["","Марфуъ: афъоли хамса, рафъ аломати ن (و — фоил)"]};
function info(w){
  var f=w.split("|"),vv=f[0].split("~"),v=vv[0],pu=vv[1]||"",c=f[1],r=f[2],mn=f[3];
  if(mn.charAt(0)=="!")mn=mn.slice(1);
  var e=ends(v),ty="",role="",why="",m=r.match(/^\[\[(.*?)\]\]\.?\s*([\s\S]*)$/);
  if(m){ty=m[1];r=m[2]}
  var ov=OVK[plain(v)];
  if(ov){role=ov[0];why=ov[1]}
  else if(c=="R"||c=="N"||c=="J"){
    role=r;
    why="Бу ўринда сўз "+T[c][0]+" бўлади, шунинг учун охирига "+T[c][1]+" қўйилади.";
    if(/[\u064B\u064C\u064D]$/.test(v))why+=" Танвин: ноаниқ исм.";
  }else{
    var k=r.indexOf(". "),p1=k<0?r:r.slice(0,k),p2=k<0?"":r.slice(k+2);
    if(/мабний/.test(p1)){why=p1;role=p2}else{role=p1;why=p2}
  }
  return {v:v,e:e,ty:ty,role:role,why:why,mn:mn,c:c,pu:pu};
}

