  au.addEventListener("seeked",function(){if(progSeek)progSeek=false;else{stopAt=null;if(loopL>=0)setLoop(-1)}lastI=-2;tick()});
  au.addEventListener("pause",function(){ppi();if(au.currentTime<(stopAt||0)-0.05||loopL<0){if(loopL>=0)setLoop(-1)}stopAt=null;tick()});
